func (r BookingRequest) Validate() error {
	var errs []error
	if r.Seats < 1 || r.Seats > 20 {
		errs = append(errs, fmt.Errorf("seats: %d out of range", r.Seats))
	}
	if r.Date == "" {
		errs = append(errs, errors.New("date: is missing"))
	}
	return errors.Join(errs...) // nil when every check passed
}

